export function normalizePhoneE164(raw) {
  const digits = raw.replace(/[^0-9+]/g, '');
  return digits.startsWith('+') ? digits : '+' + digits;
}

export function formatPhoneDisplay(e164) {
  return e164.slice(0, 3) + ' ' + e164.slice(3);
}

export function normalizeEmail(raw) {
  return raw.trim().toLowerCase();
}

// webhook sender
const WEBHOOK_BACKOFF_MS: u64 = 750;
const WEBHOOK_MAX_ATTEMPTS: u32 = 6;

// email sender
const EMAIL_BACKOFF_MS: u64 = 250;
const EMAIL_MAX_ATTEMPTS: u32 = 4;

export function vatLabel(rate: number): string {
  return `ПДВ ${rate * 100}%`;
}
